{"title": "Cortex XDR explorer - endpoint estate", "type": "vega", "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Endpoint estate by operating system and protection state.",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": 4,
  "signals": [],
  "data": [
    {
      "name": "raw",
      "url": {
        "%context%": true,
        "%timefield%": "timestamp",
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    },
                    {
                      "term": {
                        "data.cortex.event_type": "endpoint"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "os": {
                  "terms": {
                    "field": "data.cortex.os_type",
                    "size": 20
                  },
                  "aggs": {
                    "inner": {
                      "terms": {
                        "field": "data.cortex.operational_status",
                        "size": 10
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.scoped.os.buckets"
      },
      "transform": [
        {
          "type": "flatten",
          "fields": [
            "inner.buckets"
          ],
          "as": [
            "inner"
          ]
        },
        {
          "type": "formula",
          "expr": "replace(datum.key, 'AGENT_OS_', '')",
          "as": "os"
        },
        {
          "type": "formula",
          "expr": "datum.inner.key",
          "as": "protection"
        },
        {
          "type": "formula",
          "expr": "datum.inner.doc_count",
          "as": "count"
        },
        {
          "type": "formula",
          "expr": "datum.protection === 'UNPROTECTED' ? 100 : datum.protection === 'PARTIALLY_PROTECTED' ? 55 : 0",
          "as": "risk"
        },
        {
          "type": "filter",
          "expr": "datum.count > 0"
        }
      ]
    },
    {
      "name": "tree",
      "source": "raw",
      "transform": [
        {
          "type": "nest",
          "keys": [
            "os"
          ],
          "generate": true
        },
        {
          "type": "treemap",
          "field": "count",
          "method": "squarify",
          "padding": 2,
          "round": true,
          "sort": {
            "field": "value",
            "order": "descending"
          },
          "size": [
            {
              "signal": "width"
            },
            {
              "signal": "height"
            }
          ]
        }
      ]
    },
    {
      "name": "leaves",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "!datum.children"
        }
      ]
    },
    {
      "name": "groups",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.children"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "risk",
      "type": "linear",
      "domain": [
        0,
        100
      ],
      "range": {
        "scheme": "yellowgreen"
      },
      "reverse": true
    }
  ],
  "legends": [
    {
      "fill": "risk",
      "title": "Risk",
      "orient": "bottom-right"
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {
        "data": "leaves"
      },
      "encode": {
        "enter": {
          "stroke": {
            "value": "#fff"
          },
          "tooltip": {
            "signal": "datum.os + ' / ' + datum.protection + ': ' + datum.count + ' endpoints'"
          }
        },
        "update": {
          "x": {
            "field": "x0"
          },
          "y": {
            "field": "y0"
          },
          "x2": {
            "field": "x1"
          },
          "y2": {
            "field": "y1"
          },
          "fill": {
            "scale": "risk",
            "field": "risk"
          }
        }
      }
    },
    {
      "type": "rect",
      "from": {
        "data": "groups"
      },
      "encode": {
        "enter": {
          "fill": {
            "value": "transparent"
          },
          "stroke": {
            "value": "#333"
          },
          "strokeWidth": {
            "value": 2
          }
        },
        "update": {
          "x": {
            "field": "x0"
          },
          "y": {
            "field": "y0"
          },
          "x2": {
            "field": "x1"
          },
          "y2": {
            "field": "y1"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "groups"
      },
      "interactive": false,
      "encode": {
        "enter": {
          "font": {
            "value": "Helvetica Neue, Arial"
          },
          "fontSize": {
            "value": 12
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "value": "#333"
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "top"
          }
        },
        "update": {
          "x": {
            "signal": "datum.x0 + 4"
          },
          "y": {
            "signal": "datum.y0 + 3"
          },
          "text": {
            "signal": "datum.os || datum.key || datum.name"
          },
          "opacity": {
            "signal": "(datum.x1 - datum.x0) > 70 ? 1 : 0"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "leaves"
      },
      "interactive": false,
      "encode": {
        "enter": {
          "font": {
            "value": "Helvetica Neue, Arial"
          },
          "fontSize": {
            "value": 10
          },
          "fill": {
            "value": "#000"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          }
        },
        "update": {
          "x": {
            "signal": "(datum.x0 + datum.x1) / 2"
          },
          "y": {
            "signal": "(datum.y0 + datum.y1) / 2"
          },
          "text": {
            "signal": "datum.count"
          },
          "opacity": {
            "signal": "(datum.x1 - datum.x0) > 30 && (datum.y1 - datum.y0) > 18 ? 1 : 0"
          }
        }
      }
    }
  ]
}"}}

